WITH факт(вид, n) AS (SELECT 'FR', count(*) FROM project_requirements WHERE project_id = $1 AND kind = 'FR' UNION ALL SELECT 'NFR', count(*) FROM project_requirements WHERE project_id = $1 AND kind = 'NFR' UNION ALL SELECT 'TC', count(*) FROM project_checks WHERE project_id = $1 UNION ALL SELECT 'ST', count(*) FROM project_needs WHERE project_id = $1 UNION ALL SELECT 'US', count(*) FROM project_stories WHERE project_id = $1 UNION ALL SELECT 'SCR', count(*) FROM project_screens WHERE project_id = $1), строка AS (SELECT d.entity_kind AS ok, d.entity_name AS oi, regexp_replace(l.line, '«[^»]*»', ' ', 'g') AS line FROM project_documents d CROSS JOIN LATERAL regexp_split_to_table(d.content, E'\n') AS l(line) WHERE d.project_id = $1), фраза AS (SELECT s.ok, s.oi, x[1]::int AS сказано, x[2] AS вид, s.line FROM строка s CROSS JOIN LATERAL regexp_matches(s.line, (SELECT '([0-9]{2,4})\s+(?:(?:' || coalesce(string_agg(c.value, '|'), 'НЕТ-ТАКОГО-СЛОВА') || ')\s+)?`?(FR|NFR|TC|ST|US|SCR)(?:-nn|-NN)?`?(?![A-Za-z0-9-])' FROM scheme($1) c WHERE c.role = 'word.counts'), 'g') AS x WHERE s.line !~ '[~≈]?[0-9]+\s*[–—-]\s*[0-9]+' AND s.line !~ '\[0-9\]' AND NOT EXISTS (SELECT 1 FROM scheme($1) c WHERE c.role = 'word.caveat' AND lower(s.line) LIKE '%' || lower(c.value) || '%') AND NOT EXISTS (SELECT 1 FROM scheme($1) q WHERE q.role = 'word.count-prefix' AND lower(s.line) LIKE '%' || lower(q.value) || '%')) SELECT ф.ok || ' ' || coalesce(nullif(ф.oi, ''), '(одиночный)') || ' — сказано ' || ф.сказано || ' ' || ф.вид || ', а в наборе ' || к.n AS detail FROM фраза ф JOIN факт к ON к.вид = ф.вид WHERE ф.сказано <> к.n ORDER BY 1
